// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceContainerIdLike {
    internal object `asContainerId`: UniffiCallbackInterfaceContainerIdLikeMethod0 {
        override fun callback(`uniffiHandle`: Long,`ty`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeContainerIdLike.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`asContainerId`(
                    FfiConverterTypeContainerType.lift(`ty`),
                )
            }
            val writeReturn = { value: ContainerId -> uniffiOutReturn.setValue(FfiConverterTypeContainerID.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeContainerIdLike.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeContainerIdLike.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceContainerIdLike.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `asContainerId`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_loro_ffi_fn_init_callback_vtable_containeridlike(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeContainerIdLike: FfiConverter<ContainerIdLike, Long> {
    internal val handleMap = UniffiHandleMap<ContainerIdLike>()

    override fun lower(value: ContainerIdLike): Long {
        if (value is ContainerIdLikeImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ContainerIdLike {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ContainerIdLikeImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ContainerIdLike {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ContainerIdLike) = 8UL

    override fun write(value: ContainerIdLike, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


