    fun `ensureMergeableList`(`key`: kotlin.String): LoroList
    
    fun `ensureMergeableMap`(`key`: kotlin.String): LoroMap
    
    fun `ensureMergeableMovableList`(`key`: kotlin.String): LoroMovableList
    
    fun `ensureMergeableText`(`key`: kotlin.String): LoroText
    
    fun `ensureMergeableTree`(`key`: kotlin.String): LoroTree
    
    /**
     * Get the value of the map with the given key.
     */
    fun `get`(`key`: kotlin.String): ValueOrContainer?
    
    /**
     * If a detached container is attached, this method will return its corresponding attached handler.
     */
    fun `getAttached`(): LoroMap?
    
    /**
     * Get the deep value of the map.
     *
     * It will convert the state of sub-containers into a nested JSON value.
     */
    fun `getDeepValue`(): LoroValue
    
    /**
     * Get the peer id of the last editor on the given entry
     */
    fun `getLastEditor`(`key`: kotlin.String): kotlin.ULong?
    
    fun `getOrCreateCounterContainer`(`key`: kotlin.String, `child`: LoroCounter): LoroCounter
    
    fun `getOrCreateListContainer`(`key`: kotlin.String, `child`: LoroList): LoroList
    
    fun `getOrCreateMapContainer`(`key`: kotlin.String, `child`: LoroMap): LoroMap
    
    fun `getOrCreateMovableListContainer`(`key`: kotlin.String, `child`: LoroMovableList): LoroMovableList
    
    fun `getOrCreateTextContainer`(`key`: kotlin.String, `child`: LoroText): LoroText
    
    fun `getOrCreateTreeContainer`(`key`: kotlin.String, `child`: LoroTree): LoroTree
    
    /**
     * Get the shallow value of the map.
     *
     * It will not convert the state of sub-containers, but represent them as [LoroValue::Container].
     */
    fun `getValue`(): LoroValue
    
    /**
     * Get the ID of the map.
     */
    fun `id`(): ContainerId
    
    /**
     * Insert a key-value pair into the map.
     *
     * > **Note**: When calling `map.set(key, value)` on a LoroMap, if `map.get(key)` already returns `value`,
     * > the operation will be a no-op (no operation recorded) to avoid unnecessary updates.
     */
    fun `insert`(`key`: kotlin.String, `v`: LoroValueLike)
    
    fun `insertCounterContainer`(`key`: kotlin.String, `child`: LoroCounter): LoroCounter
    
    fun `insertListContainer`(`key`: kotlin.String, `child`: LoroList): LoroList
    
    fun `insertMapContainer`(`key`: kotlin.String, `child`: LoroMap): LoroMap
    
    fun `insertMovableListContainer`(`key`: kotlin.String, `child`: LoroMovableList): LoroMovableList
    
    fun `insertTextContainer`(`key`: kotlin.String, `child`: LoroText): LoroText
    
    fun `insertTreeContainer`(`key`: kotlin.String, `child`: LoroTree): LoroTree
    
    /**
     * Whether the container is attached to a document.
     */
    fun `isAttached`(): kotlin.Boolean
    
    /**
     * Whether the container is deleted.
     */
    fun `isDeleted`(): kotlin.Boolean
    
    /**
     * Whether the map is empty.
     */
    fun `isEmpty`(): kotlin.Boolean
    
    /**
     * Get the keys of the map.
     */
    fun `keys`(): kotlin.collections.List<kotlin.String>
    
    /**
     * Get the length of the map.
     */
    fun `len`(): kotlin.UInt
    
    /**
     * Subscribe the events of a container.
     *
     * The callback will be invoked when the container is changed.
     * Returns a subscription that can be used to unsubscribe.
     *
     * The events will be emitted after a transaction is committed. A transaction is committed when:
     *
     * - `doc.commit()` is called.
     * - `doc.export(mode)` is called.
     * - `doc.import(data)` is called.
     * - `doc.checkout(version)` is called.
     */
    fun `subscribe`(`subscriber`: Subscriber): Subscription?
    
    /**
     * Get the values of the map.
     */
    fun `values`(): kotlin.collections.List<ValueOrContainer>
    
    companion object
}

open class LoroMap: Disposable, AutoCloseable, LoroMapInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }
    /**
     * Create a new container that is detached from the document.
     *
     * The edits on a detached container will not be persisted.
     * To attach the container to the document, please insert it into an attached container.
     */
    constructor() :
        this(UniffiWithHandle, 
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_loro_ffi_fn_constructor_loromap_new(
    
        _status)
}
    )

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

