    fun `setListContainer`(`pos`: kotlin.UInt, `child`: LoroList): LoroList
    
    fun `setMapContainer`(`pos`: kotlin.UInt, `child`: LoroMap): LoroMap
    
    fun `setMovableListContainer`(`pos`: kotlin.UInt, `child`: LoroMovableList): LoroMovableList
    
