    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_loro_ffi_fn_free_lorounknown(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_loro_ffi_fn_clone_lorounknown(handle, status)
        }
    }

    
    /**
     * Get the container id.
     */override fun `id`(): ContainerId {
            return FfiConverterTypeContainerID.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_loro_ffi_fn_method_lorounknown_id(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
