     */
    fun `insert`(`peer`: kotlin.ULong, `start`: kotlin.Int, `end`: kotlin.Int)
    
    /**
     * Check if the VersionRange is empty
     */
    fun `isEmpty`(): kotlin.Boolean
    
    companion object
}

