/**
 * @suppress
 */
public object FfiConverterTypeVersionVector: FfiConverter<VersionVector, Long> {
    override fun lower(value: VersionVector): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): VersionVector {
        return VersionVector(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): VersionVector {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: VersionVector) = 8UL

    override fun write(value: VersionVector, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



