 */
public object FfiConverterTypeTextDelta : FfiConverterRustBuffer<TextDelta>{
    override fun read(buf: ByteBuffer): TextDelta {
        return when(buf.getInt()) {
            1 -> TextDelta.Retain(
                FfiConverterUInt.read(buf),
                FfiConverterOptionalMapStringTypeLoroValue.read(buf),
                )
            2 -> TextDelta.Insert(
                FfiConverterString.read(buf),
                FfiConverterOptionalMapStringTypeLoroValue.read(buf),
                )
            3 -> TextDelta.Delete(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TextDelta) = when(value) {
        is TextDelta.Retain -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`retain`)
                + FfiConverterOptionalMapStringTypeLoroValue.allocationSize(value.`attributes`)
            )
        }
        is TextDelta.Insert -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`insert`)
                + FfiConverterOptionalMapStringTypeLoroValue.allocationSize(value.`attributes`)
            )
        }
        is TextDelta.Delete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`delete`)
            )
        }
    }

    override fun write(value: TextDelta, buf: ByteBuffer) {
        when(value) {
            is TextDelta.Retain -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`retain`, buf)
                FfiConverterOptionalMapStringTypeLoroValue.write(value.`attributes`, buf)
                Unit
            }
            is TextDelta.Insert -> {
                buf.putInt(2)
                FfiConverterString.write(value.`insert`, buf)
                FfiConverterOptionalMapStringTypeLoroValue.write(value.`attributes`, buf)
                Unit
            }
            is TextDelta.Delete -> {
                buf.putInt(3)
                FfiConverterUInt.write(value.`delete`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





