/**
 * @suppress
 */
public object FfiConverterTypeTreeExternalDiff : FfiConverterRustBuffer<TreeExternalDiff>{
    override fun read(buf: ByteBuffer): TreeExternalDiff {
        return when(buf.getInt()) {
            1 -> TreeExternalDiff.Create(
                FfiConverterTypeTreeParentId.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> TreeExternalDiff.Move(
                FfiConverterTypeTreeParentId.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeTreeParentId.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> TreeExternalDiff.Delete(
                FfiConverterTypeTreeParentId.read(buf),
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: TreeExternalDiff) = when(value) {
        is TreeExternalDiff.Create -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTreeParentId.allocationSize(value.`parent`)
                + FfiConverterUInt.allocationSize(value.`index`)
                + FfiConverterString.allocationSize(value.`fractionalIndex`)
            )
        }
        is TreeExternalDiff.Move -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTreeParentId.allocationSize(value.`parent`)
                + FfiConverterUInt.allocationSize(value.`index`)
                + FfiConverterString.allocationSize(value.`fractionalIndex`)
                + FfiConverterTypeTreeParentId.allocationSize(value.`oldParent`)
                + FfiConverterUInt.allocationSize(value.`oldIndex`)
            )
        }
        is TreeExternalDiff.Delete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTreeParentId.allocationSize(value.`oldParent`)
                + FfiConverterUInt.allocationSize(value.`oldIndex`)
            )
        }
    }

    override fun write(value: TreeExternalDiff, buf: ByteBuffer) {
        when(value) {
            is TreeExternalDiff.Create -> {
                buf.putInt(1)
                FfiConverterTypeTreeParentId.write(value.`parent`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                FfiConverterString.write(value.`fractionalIndex`, buf)
                Unit
            }
            is TreeExternalDiff.Move -> {
                buf.putInt(2)
                FfiConverterTypeTreeParentId.write(value.`parent`, buf)
                FfiConverterUInt.write(value.`index`, buf)
                FfiConverterString.write(value.`fractionalIndex`, buf)
                FfiConverterTypeTreeParentId.write(value.`oldParent`, buf)
                FfiConverterUInt.write(value.`oldIndex`, buf)
                Unit
            }
            is TreeExternalDiff.Delete -> {
                buf.putInt(3)
                FfiConverterTypeTreeParentId.write(value.`oldParent`, buf)
                FfiConverterUInt.write(value.`oldIndex`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





